*/
const AISkeletonText = ({ className, ...rest }) => {
	const prefix = usePrefix();
	const aiSkeletonTextClasses = cx(className, { [`${prefix}--skeleton__text--ai`]: true });
	return /* @__PURE__ */ jsx(SkeletonText, {
		className: aiSkeletonTextClasses,
		...rest
